using System;

class Program
{
    static void Main()
    {
        Span<nint> signedSpan = stackalloc nint[4];
        signedSpan[0] = 42;
        signedSpan[1] = -7;
        signedSpan[2] = nint.MaxValue;
        signedSpan[3] = nint.MinValue;

        Console.WriteLine("Span<nint> via stackalloc:");
        for (int i = 0; i < signedSpan.Length; i++)
            Console.WriteLine($"  [{i}] = {signedSpan[i]}");

        Span<nuint> unsignedSpan = stackalloc nuint[3];
        unsignedSpan[0] = 100;
        unsignedSpan[1] = nuint.MaxValue;
        unsignedSpan[2] = 0;

        Console.WriteLine("Span<nuint> via stackalloc:");
        for (int i = 0; i < unsignedSpan.Length; i++)
            Console.WriteLine($"  [{i}] = {unsignedSpan[i]}");

        Console.WriteLine($"\nnint size: {sizeof(nint)} bytes");
        Console.WriteLine($"nuint size: {sizeof(nuint)} bytes");
    }
}
EOF
dotnet-script test.cs 2>&1 || dotnet run --project . 2>&1 || { echo "---Trying csc---"; which csc && csc test.cs -out:test.exe && mono test.exe; }

